5 5 5 5 8 5 5 5 5 5
5 8 5 5 8 5 5 5 5 5
8 8 8 8 8 8 8 8 8 8
8 8 8 8 8 8 8 8 8 8
5 5 5 5 8 5 5 5 5 5
5 5 5 5 8 5 5 8 5 5
8 8 8 8 8 8 8 8 8 8
5 5 5 8 8 5 5 5 5 5"""

input_grid = [list(map(int, line.split())) for line in input_grid_str.strip().split('\n')]
h, w = len(input_grid), len(input_grid[0])

# Find horizontal full 8 rows
horiz_full = []
for r in range(h):
    if all(input_grid[r][c] == 8 for c in range(w)):
        horiz_full.append(r)
print(f"Horiz full 8: {horiz_full}")

# Find vertical full 8 cols
vert_full = []
for c in range(w):
    if all(input_grid[r][c] == 8 for r in range(h)):
        vert_full.append(c)
print(f"Vert full 8: {vert_full}")

horiz_s = set(horiz_full)
vert_s = set(vert_full)

# Build regions: each non-separator cell belongs to one region
# For horizontal: between separator rows
# For vertical: between separator columns

# Horizontal regions indices
# seg 0: rows < first sep
# seg 1: rows between sep 0 and sep 1
# etc.
def find_region(r, sep_rows):
    for i, sr in enumerate(sorted(sep_rows)):
        if r < sr:
            return i
        if i < len(sep_rows) - 1 and r >= sr and r < sep_rows[i+1]:
            return i + 1
    return len(sep_rows)  # after all separators

def find_region_col(c, sep_cols):
    for i, sc in enumerate(sorted(sep_cols)):
        if c < sc:
            return i
        if i < len(sep_cols) - 1 and c >= sc and c < sep_cols[i+1]:
            return i + 1
    return len(sep_cols)

# Precompute region index for each cell
cell_horiz_idx = {}
for r in range(h):
    if r in horiz_s:
        cell_horiz_idx[r] = 'SEP'  # separator row
    else:
        cell_horiz_idx[r] = find_region(r, horiz_full)

cell_vert_idx = {}
for c in range(w):
    if c in vert_s:
        cell_vert_idx[c] = 'SEP'  # separator col
    else:
        cell_vert_idx[c] = find_region_col(c, vert_full)

# Now count for each region whether it has any 8 in INPUT
from collections import defaultdict
region_has = defaultdict(lambda: {'5': 0, '8': 0})

for r in range(h):
    for c in range(w):
        hr = cell_horiz_idx[r]
        vr = cell_vert_idx[c]
        val = input_grid[r][c]
        region_has[(hr, vr)][str(val)] += 1

print("\nRegion summary (row_col, count_5, count_8):")
for key, vals in sorted(region_has.items()):
    hr, vr = key
    print(f"Region ({hr}, {vr}): 5s={vals['5']}, 8s={vals['8']}")

# Build output: within each region, if count_8 > 0, entire region = 8, else = 0
# Separators = 5 (stay 5)
output = [[0]*w for _ in range(h)]
for r in range(h):
    for c in range(w):
        if r in horiz_s or c in vert_s:
            output[r][c] = 5
        else:
            hr, vr = cell_horiz_idx[r], cell_vert_idx[c]
            if region_has[(hr, vr)]['8'] > 0:
                output[r][c] = 8
            else:
                output[r][c] = 0

print("\nOutput:")
for row in output:
    print(row)
print(f"\nJSON: {json.dumps(output)}")
